mapper.sql:
WHERE del_yn = 'N'

  AND create_at >= #{cond.from}


  AND create_at < #{cond.toExclusive}


  AND category = #{cond.category}




  AND title LIKE CONCAT('%', #{cond.keywordPattern}, '%') ESCAPE '!'


  AND content LIKE CONCAT('%', #{cond.keywordPattern}, '%') ESCAPE '!'


  AND (title LIKE CONCAT('%', #{cond.keywordPattern}, '%') ESCAPE '!'
       OR content LIKE CONCAT('%', #{cond.keywordPattern}, '%') ESCAPE '!')

mapper.insert:
    	INSERT INTO notice (
			category
		  , title
		  , content
		  , create_emp_no
		) VALUES (
			#{category}			
		  , #{title}
		  , #{content}
		  , #{createEmpNo}
		)
